:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-dark: #b8324a;
  --highlight: #0f3460;
  --border: #2a2a4a;
  --focus: #f5c542;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 20%, #1f1f3a 0%, transparent 50%),
                    radial-gradient(circle at 80% 80%, #1f1f3a 0%, transparent 50%);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
  padding: 24px;
  width: 100%;
  max-width: 520px;
  border-radius: 4px;
}

h1 {
  margin: 0 0 20px;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--accent-dark);
}

.task-form {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

#task-input {
  flex: 1 1 160px;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  border-radius: 2px;
}

#task-input:focus, select:focus, button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

select {
  padding: 10px 8px;
  font-size: 1rem;
  font-family: var(--font);
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  border-radius: 2px;
  cursor: pointer;
}

.btn, .filter-btn, .task-btn {
  font-family: var(--font);
  font-size: 1rem;
  cursor: pointer;
  border: 3px solid var(--border);
  border-radius: 2px;
  transition: background 0.15s, transform 0.05s;
}

.btn {
  padding: 10px 18px;
  background: var(--accent);
  color: #fff;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.btn:hover { background: var(--accent-dark); }
.btn:active { transform: translate(2px, 2px); }

.filters {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.filter-btn {
  padding: 8px 14px;
  background: var(--highlight);
  color: var(--text);
}

.filter-btn:hover { background: #1a4a7a; }
.filter-btn:active { transform: translate(1px, 1px); }
.filter-btn.active {
  background: var(--accent);
  color: #fff;
  font-weight: bold;
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: var(--bg);
  border: 3px solid var(--border);
  border-left-width: 8px;
  border-radius: 2px;
}

.task-item.priority-high { border-left-color: var(--accent); }
.task-item.priority-medium { border-left-color: #f5a623; }
.task-item.priority-low { border-left-color: #4caf50; }

.task-item.completed .task-text {
  text-decoration: line-through;
  opacity: 0.55;
}

.task-text {
  flex: 1;
  word-break: break-word;
  font-size: 1rem;
}

.task-btn {
  padding: 6px 10px;
  background: var(--highlight);
  color: var(--text);
  font-size: 0.9rem;
  min-width: 44px;
  min-height: 36px;
}

.task-btn:hover { background: #1a4a7a; }
.task-btn:active { transform: translate(1px, 1px); }
.task-btn.delete {
  background: var(--accent-dark);
}
.task-btn.delete:hover { background: var(--accent); }

.empty-msg {
  text-align: center;
  opacity: 0.6;
  margin: 16px 0 0;
  font-style: italic;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 420px) {
  .card { padding: 16px; }
  h1 { font-size: 1.4rem; }
  .task-btn { padding: 6px 8px; }
}

(function () {
  'use strict';

  const taskForm = document.getElementById('task-form');
  const taskInput = document.getElementById('task-input');
  const prioritySelect = document.getElementById('priority-select');
  const taskList = document.getElementById('task-list');
  const emptyMsg = document.getElementById('empty-msg');
  const filterBtns = document.querySelectorAll('.filter-btn');

  let tasks = [];
  let currentFilter = 'all';
  let nextId = 1;

  const priorityOrder = { high: 0, medium: 1, low: 2 };

  function sortTasks() {
    tasks.sort(function (a, b) {
      if (a.completed !== b.completed) return a.completed ? 1 : -1;
      return priorityOrder[a.priority] - priorityOrder[b.priority];
    });
  }

  function render() {
    sortTasks();
    taskList.innerHTML = '';

    const filtered = tasks.filter(function (t) {
      if (currentFilter === 'active') return !t.completed;
      if (currentFilter === 'completed') return t.completed;
      return true;
    });

    emptyMsg.hidden = filtered.length > 0;

    filtered.forEach(function (task) {
      const li = document.createElement('li');
      li.className = 'task-item priority-' + task.priority + (task.completed ? ' completed' : '');

      const span = document.createElement('span');
      span.className = 'task-text';
      span.textContent = task.text;

      const toggleBtn = document.createElement('button');
      toggleBtn.type = 'button';
      toggleBtn.className = 'task-btn';
      toggleBtn.textContent = task.completed ? 'Undo' : 'Done';
      toggleBtn.setAttribute('aria-label', (task.completed ? 'Mark as active: ' : 'Mark as completed: ') + task.text);
      toggleBtn.addEventListener('click', function () {
        task.completed = !task.completed;
        render();
      });

      const delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.className = 'task-btn delete';
      delBtn.textContent = 'Del';
      delBtn.setAttribute('aria-label', 'Delete task: ' + task.text);
      delBtn.addEventListener('click', function () {
        tasks = tasks.filter(function (t) { return t.id !== task.id; });
        render();
      });

      li.appendChild(span);
      li.appendChild(toggleBtn);
      li.appendChild(delBtn);
      taskList.appendChild(li);
    });
  }

  taskForm.addEventListener('submit', function (e) {
    e.preventDefault();
    const text = taskInput.value.trim();
    if (!text) return;
    tasks.push({
      id: nextId++,
      text: text,
      priority: prioritySelect.value,
      completed: false
    });
    taskInput.value = '';
    taskInput.focus();
    render();
  });

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      currentFilter = btn.dataset.filter;
      filterBtns.forEach(function (b) {
        const isActive = b === btn;
        b.classList.toggle('active', isActive);
        b.setAttribute('aria-pressed', String(isActive));
      });
      render();
    });
  });

  render();
})();
